// HMAC helpers for the Agent Games signed-task protocol.
//
// VERIFIED (official docs, https://agentgames.zkverify.io/build + /rules):
// - The platform signs every task delivery with the per-agent HMAC secret in
//   the `x-agent-games-signature` header, computed over the RAW request body.
// - The agent must verify that signature BEFORE parsing or processing.
// - Every response is signed with `x-agent-games-signature` over the RAW
//   response body.
// - The secret is a random 32 bytes generated by the platform at registration
//   and shown exactly once.
//
// ASSUMPTIONS (NOT documented on the public pages — confirm against the
// signed preflight / first practice task; see README.md):
// - Algorithm is HMAC-SHA256.
// - Header value is the lowercase hex digest of the HMAC over the raw body.
// - The secret as displayed at registration is either 64 hex chars or a
//   base64 string; parseSecret() accepts both, plus a raw UTF-8 string.
// - verify() additionally accepts a `sha256=<hex>` prefixed header and a
//   base64-encoded digest, so a format surprise fails closed with a clear log
//   instead of silently rejecting every task.
import crypto from "node:crypto";

/** Parse the platform-issued secret from its displayed form into raw bytes. */
export function parseSecret(raw) {
  if (typeof raw !== "string" || raw.length === 0) {
    throw new Error("AGENT_GAMES_HMAC_SECRET is empty");
  }
  const s = raw.trim();
  if (/^[0-9a-fA-F]{64}$/.test(s)) return Buffer.from(s, "hex");
  if (/^[A-Za-z0-9+/]{43}=$/.test(s)) return Buffer.from(s, "base64");
  if (/^[A-Za-z0-9+/]{44}$/.test(s) && s.endsWith("=")) return Buffer.from(s, "base64");
  // Fallback: treat as a raw UTF-8 passphrase (NOT the platform format).
  return Buffer.from(s, "utf8");
}

/** Hex HMAC-SHA256 of raw bytes with the secret. */
export function hmacHex(secretBytes, rawBody) {
  return crypto.createHmac("sha256", secretBytes).update(rawBody).digest("hex");
}

/** Raw HMAC-SHA256 bytes (for base64-form comparison). */
export function hmacBytes(secretBytes, rawBody) {
  return crypto.createHmac("sha256", secretBytes).update(rawBody).digest();
}

/**
 * Verify an incoming `x-agent-games-signature` header against the raw body.
 * Returns { ok: boolean, form: string|null } where form names which encoding
 * matched ("hex" | "sha256=hex" | "base64" | null). Timing-safe comparison.
 */
export function verifySignature(secretBytes, rawBody, headerValue) {
  if (!headerValue || typeof headerValue !== "string") return { ok: false, form: null };
  const expectedHex = hmacHex(secretBytes, rawBody);
  const expectedBuf = hmacBytes(secretBytes, rawBody);
  const candidates = [];
  const v = headerValue.trim();
  candidates.push(["hex", v]);
  if (v.toLowerCase().startsWith("sha256=")) candidates.push(["sha256=hex", v.slice(7)]);
  // base64 form: decode header, compare raw bytes
  try {
    const b64 = Buffer.from(v, "base64");
    if (b64.length === 32 && b64.toString("base64").replace(/=+$/, "") === v.replace(/=+$/, "")) {
      if (crypto.timingSafeEqual(b64, expectedBuf)) return { ok: true, form: "base64" };
    }
  } catch { /* not base64 — fall through */ }
  for (const [form, candidate] of candidates) {
    if (candidate.length !== expectedHex.length) continue;
    try {
      if (crypto.timingSafeEqual(Buffer.from(candidate.toLowerCase(), "utf8"), Buffer.from(expectedHex, "utf8"))) {
        return { ok: true, form };
      }
    } catch { /* length/type mismatch — not a match */ }
  }
  return { ok: false, form: null };
}

/** Sign a raw response body: returns the hex HMAC-SHA256 for the header. */
export function signBody(secretBytes, rawBody) {
  return hmacHex(secretBytes, rawBody);
}
